// Dynamic import for analytics chart
const HeavyChart = React.lazy(() => import('./charts/HeavyChart'));

// Visibility gate wrapper
function useVisible(ref) {
  const [visible, setVisible] = React.useState(false);
  React.useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => setVisible(entry.isIntersecting),
      { threshold: 0.1 }
    );
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [ref]);
  return visible;
}
```

## Why This Is Asked
Tests understanding of closures, promise sharing, and TTL eviction in a small utility.

## Key Concepts
- Closures and per-id state
- Promise deduplication for in-flight calls
- TTL-based eviction and error handling

## Code Example
```javascript
function createMemoizedAsync(fn, ttl) {
  const cache = new Map();
  return async (id) => {
    const now = Date.now();
    const entry = cache.get(id);
    if (entry && now - entry.t < ttl) return entry.p;
    const p = fn(id);
    cache.set(id, { t: now, p });
    setTimeout(() => {
      const e = cache.get(id);
      if (e && e.p === p) cache.delete(id);
    }, ttl);
    try {
      return await p;
    } catch (e) {
      cache.delete(id);
      throw e;
    }
  };
}
```

